arguments.keystrokes:
{
  echo 'Subject: '$(openssl x509 -in /app/ssl/server.crt -noout -subject)
  echo 'Validity (OpenSSL format):'
  openssl x509 -in /app/ssl/server.crt -noout -dates
  start=$(openssl x509 -in /app/ssl/server.crt -noout -startdate | cut -d'=' -f2-)
  end=$(openssl x509 -in /app/ssl/server.crt -noout -enddate | cut -d'=' -f2-)
  echo 'Valid From (YYYY-MM-DD): '$(date -u -d "$start" +%Y-%m-%d 2>/dev/null || echo "$start")
  echo 'Valid Until (YYYY-MM-DD): '$(date -u -d "$end" +%Y-%m-%d 2>/dev/null || echo "$end")
  echo 'SHA-256 Fingerprint: '$(openssl x509 -in /app/ssl/server.crt -noout -fingerprint -sha256)
} > /app/ssl/verification.txt && chmod 644 /app/ssl/verification.txt
